import {ownRecord,denseValues} from './state-validation.mjs';
export const compositionActivity={id:'composition',stage:'7y',key:'7y:composition',area:'Creatividad',type:'digital',label:'9–12 años',kind:'interactive',title:'Crear y mirar de otra manera',unit:'Un cartel, varias versiones',copy:'Combina elementos de un cartel imaginario. Después cambia una condición y compara tus versiones.',goal:'Componer, revisar una alternativa y señalar una razón de diseño sin una única solución.',duration:'A tu ritmo · puedes parar en cualquier paso',support:'Con ayuda si la necesitas; puedes señalar y otra persona pulsar',transfer:'En papel, dibuja otra versión con dos formas. Señala qué mantuviste y qué cambiaste. No hace falta fotografiarla ni subirla.'};
export const pieces={book:'Libro',leaf:'Hoja',star:'Estrella',arrow:'Flecha',empty:'Vacío'};
export const reasons={focus:'Quise destacar un elemento',space:'Quise dejar más espacio',group:'Quise agrupar elementos',contrast:'Quise distinguir formas sin color',explore:'Quise probar otra posibilidad'};
export const newComposition=()=>({page:0,cells:Array(9).fill(null),original:null,undo:null,tool:'book',reason:null,hint:false});
export function validateComposition(raw){
 ownRecord(raw,['page','cells','original','undo','tool','reason','hint']);
 if(!Number.isInteger(raw.page)||raw.page<0||raw.page>2||typeof raw.tool!=='string'||!Object.hasOwn(pieces,raw.tool)||!(raw.reason===null||typeof raw.reason==='string'&&Object.hasOwn(reasons,raw.reason))||typeof raw.hint!=='boolean')throw Error('Invalid composition');
 const allowed=[null,'book','leaf','star','arrow'],cells=denseValues(raw.cells,allowed,9,true),original=raw.original===null?null:denseValues(raw.original,allowed,9,true),undo=raw.undo===null?null:denseValues(raw.undo,allowed,9,true);
 if((raw.page===0&&original!==null)||(raw.page>0&&(!original||!original.some(Boolean)))||(raw.page===2&&(!cells.some(Boolean)||!raw.reason)))throw Error('Invalid composition step');
 return {...raw,cells,original,undo};
}
export function putPiece(s,index){
 if(!Number.isInteger(index)||index<0||index>8||s.page===2)throw Error('Invalid cell');
 const piece=s.tool==='empty'?null:s.tool;if(s.cells[index]===piece)return false;s.undo=[...s.cells];s.cells[index]=piece;s.reason=null;return true;
}
export function undoComposition(s){if(!s.undo)return false;s.cells=[...s.undo];s.undo=null;s.reason=null;return true;}
export function nextComposition(s){if(!s.cells.some(Boolean)||s.page===2||s.page===1&&!s.reason)return false;if(s.page===0)s.original=[...s.cells];s.page++;s.undo=null;s.hint=false;return true;}
export function compositionDifference(s){return s.original?s.cells.filter((x,i)=>x!==s.original[i]).length:0;}
const paths={book:'M12 13Q23 8 32 15Q41 8 52 13V48Q41 43 32 50Q23 43 12 48Z M32 15V50',leaf:'M15 50Q4 13 51 10Q58 46 15 50Z M15 50L43 20 M27 37L23 23 M34 29L45 31',star:'M32 8L39 24L56 25L43 37L47 54L32 45L17 54L21 37L8 25L25 24Z',arrow:'M10 26H36V14L55 32L36 50V38H10Z'};
const art=id=>id?`<svg viewBox="0 0 64 64" aria-hidden="true" class="compose-art piece-${id}"><path d="${paths[id]}" stroke="currentColor" stroke-width="3" stroke-linejoin="round" fill="none"/></svg>`:'<span class="compose-empty" aria-hidden="true">＋</span>';
function board(cells,{editable=false,mono=false}={}){return `<div class="compose-board ${mono?'compose-mono':''}" ${editable?'role="group" aria-label="Composición editable, tres filas y tres columnas"':'role="group" aria-label="Composición de referencia"'}>${cells.map((piece,i)=>editable?`<button type="button" class="compose-cell" data-compose-cell="${i}" aria-label="Fila ${Math.floor(i/3)+1}, columna ${i%3+1}: ${piece?pieces[piece]:'vacío'}. Colocar elemento elegido.">${art(piece)}<span>${piece?pieces[piece]:'Vacío'}</span></button>`:`<div class="compose-cell"><span class="sr-only">Fila ${Math.floor(i/3)+1}, columna ${i%3+1}: </span>${art(piece)}<span>${piece?pieces[piece]:'Vacío'}</span></div>`).join('')}</div>`;}
export function renderComposition(root,st,{finish}){
 const s=st.composition??=newComposition(),changed=compositionDifference(s),hasPieces=s.cells.some(Boolean);
 const redraw=selector=>{renderComposition(root,st,{finish});root.querySelector(selector)?.focus();};
 root.innerHTML=`<section class="composition" aria-labelledby="compose-title"><p class="eyebrow">Creatividad · 9–12 años · sin puntuación</p><h4 id="compose-title" tabindex="-1">Un cartel, varias versiones</h4><p>Cartel imaginario: «Un rincón para leer». Las figuras son elementos de diseño, no señales de seguridad. No hay una composición correcta ni un perfil personal que descubrir.</p><ol class="construction-steps" aria-label="Recorrido"><li ${s.page===0?'aria-current="step"':''}>Crear</li><li ${s.page===1?'aria-current="step"':''}>Cambiar una condición</li><li ${s.page===2?'aria-current="step"':''}>Comparar y cerrar</li></ol><p>${s.page===0?'Elige un elemento y pulsa una casilla. Puedes repetir, sustituir o borrar elementos; los espacios vacíos también forman parte del cartel.':s.page===1?'Nueva condición: imagina que el cartel se imprimirá sin color. Tu primera versión queda como referencia; la editable usa solo formas en blanco y negro. Puedes mover el foco, agrupar o conservar tu composición.':'Creaste una versión y exploraste otra condición. Esta comparación no mide una capacidad ni demuestra que una opción sea mejor.'}</p>${s.page<2?`<fieldset><legend>1. Elige qué colocar</legend><div class="compose-palette">${Object.entries(pieces).map(([id,label])=>`<button type="button" class="action secondary" data-compose-tool="${id}" aria-pressed="${s.tool===id}">${label==='Vacío'?'Borrar una casilla':label}</button>`).join('')}</div></fieldset><p id="compose-instruction">2. Pulsa una casilla para ${s.tool==='empty'?'dejarla vacía':'colocar '+pieces[s.tool].toLowerCase()}. Puedes usar Tab y Enter o Espacio, sin arrastrar.</p>`:''}<div class="compose-versions ${s.page===0?'compose-single':''}">${s.original?`<article><h5>Primera versión · color</h5>${board(s.original)}</article>`:''}<article><h5>${s.page===0?'Tu cartel':s.page===1?'Versión editable · sin color':'Tu alternativa · sin color'}</h5>${board(s.cells,{editable:s.page<2,mono:s.page>0})}</article></div><p id="compose-status" role="status">Elementos colocados: ${s.cells.filter(Boolean).length}.${s.original?' '+changed+(changed===1?' casilla distinta':' casillas distintas')+' respecto a tu primera versión.':''}</p>${s.page<2?`<div class="controls"><button type="button" class="action secondary" id="compose-undo" ${s.undo?'':'disabled'}>Deshacer el último cambio</button><button type="button" class="action secondary" id="compose-hint">Una idea para probar</button></div><p id="compose-hint-text" role="status" tabindex="-1">${s.hint?(s.page===0?'Prueba un elemento en el centro y otro en un borde. Mira qué cambia al dejar una casilla vacía; no hay que llenar las nueve.':'Sin color, compara las siluetas y la separación. Puedes repetir una forma o dejar espacio alrededor de la que quieras destacar. Conservar la versión también es válido.'):''}</p>`:''}${s.page===1?`<fieldset><legend>3. Señala una intención de diseño</legend><p>Elige una frase sobre el cartel. No evaluamos tu personalidad ni si lograste esa intención.</p><div class="controls">${Object.entries(reasons).map(([id,label])=>`<button type="button" class="action secondary" data-compose-reason="${id}" aria-pressed="${s.reason===id}">${label}</button>`).join('')}</div></fieldset>`:''}${s.page<2?`<p>${!hasPieces?'Coloca al menos un elemento si quieres comparar versiones. También puedes terminar por hoy.':s.page===1&&!s.reason?'Elige una intención para llevarla al cierre, o termina cuando quieras.':'Tu siguiente paso está disponible.'}</p><button type="button" class="action primary" id="compose-next" ${hasPieces&&(s.page===0||s.reason)?'':'disabled'}>${s.page===0?'Probar sin color':'Comparar y cerrar'}</button>`:`<p><strong>Tu intención:</strong> ${reasons[s.reason]}.</p><p>${changed?'Cambiaste uno o más elementos del cartel al trabajar sin color.':'Conservaste la distribución y cambió el color. Ambas decisiones son posibles.'} Puedes señalar qué mirarías primero y probar otra alternativa en papel.</p><p>Fuera de pantalla: dibuja otra versión con dos formas. Cuenta qué conservaste y qué cambiaste, hablando o señalando. No hace falta escribir, fotografiar ni subir nada.</p><div class="controls"><button type="button" class="action secondary" id="compose-revise">Probar otra alternativa</button><button type="button" class="action primary" id="compose-finish">Terminar por hoy</button></div>`}<p class="quiet">Pausa, salida y ayuda de Luma siguen arriba. Las elecciones se guardan solo en este navegador cuando el aviso lo confirma.</p></section>`;
 const on=(id,fn)=>{const el=root.querySelector('#'+id);if(el)el.onclick=fn;};
 root.querySelectorAll('[data-compose-tool]').forEach(el=>el.onclick=()=>{s.tool=el.dataset.composeTool;redraw(`[data-compose-tool="${s.tool}"]`);});
 root.querySelectorAll('[data-compose-cell]').forEach(el=>el.onclick=()=>{putPiece(s,Number(el.dataset.composeCell));redraw(`[data-compose-cell="${el.dataset.composeCell}"]`);});
 root.querySelectorAll('[data-compose-reason]').forEach(el=>el.onclick=()=>{s.reason=el.dataset.composeReason;redraw(`[data-compose-reason="${s.reason}"]`);});
 on('compose-undo',()=>{undoComposition(s);redraw('[data-compose-cell]');});
 on('compose-hint',()=>{s.hint=true;redraw('#compose-hint-text');});
 on('compose-next',()=>{if(nextComposition(s))redraw('#compose-title');});
 on('compose-revise',()=>{s.page=1;s.reason=null;redraw('#compose-title');});
 on('compose-finish',finish);
}
